-- Resync identity sequences: explicit-id inserts do not advance them, and
-- without this the first admin insert would fail with a duplicate-PK error.
select setval(pg_get_serial_sequence('public.categories', 'id'), (select max(id) from public.categories));
select setval(pg_get_serial_sequence('public.subcategories', 'id'), (select max(id) from public.subcategories));
select setval(pg_get_serial_sequence('public.topics', 'id'), (select max(id) from public.topics));
select setval(pg_get_serial_sequence('public.units', 'id'), (select max(id) from public.units));
select setval(pg_get_serial_sequence('public.lessons', 'id'), (select max(id) from public.lessons));

commit;
